#include <bits/stdc++.h>
using namespace std;
struct TreeNode {
    int val; TreeNode *left, *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *l, TreeNode *r) : val(x), left(l), right(r) {}
};

files.driver:
// level-order input, -1 = no child
TreeNode* buildTree() {
    int v; if (!(cin >> v) || v == -1) return NULL;
    TreeNode* root = new TreeNode(v);
    queue<TreeNode*> q; q.push(root);
    while (!q.empty()) {
        TreeNode* p = q.front(); q.pop();
        int l, r; cin >> l >> r;
        if (l != -1) { p->left = new TreeNode(l); q.push(p->left); }
        if (r != -1) { p->right = new TreeNode(r); q.push(p->right); }
    }
    return root;
}
int main() {
    TreeNode* root = buildTree();
    vector<int> ans = Solution().preorderTraversal(root);
    cout << "preorder = [";
    for (int i = 0; i < (int)ans.size(); i++) cout << (i ? "," : "") << ans[i];
    cout << "]" << endl;
}

